  static void TestSidebarConsistency(Window owner,FilePanel panel,string root,Action<bool,string> check){
   var header=(GridViewColumnHeader)((GridView)panel.List.View).Columns[0].Header;header.ApplyTemplate();var columnFrame=(Border)header.Template.FindName("ColumnFrame",header);check(columnFrame.BorderThickness.Right==1&&columnFrame.BorderThickness.Bottom==1,"file headers render separators between columns and below the header");
   var folderTab=FluentUiTests.Children<Border>(panel).First(x=>Convert.ToString(x.Tag)=="panel-tab-face");check(folderTab.BorderThickness.Top==0&&folderTab.BorderThickness.Bottom==2&&Object.ReferenceEquals(folderTab.BorderBrush,FluentTheme.Accent),"folder tab uses a blue underline without an enclosing outline");
   var analyzer=new DiskAnalyzerWindow(owner,root,null,false);try{Open(analyzer);Click(More(analyzer));Pump(analyzer);foreach(TabItem tab in analyzer.AnalyzerPages.Items){tab.ApplyTemplate();check(tab.Template.FindName("NavFrame",tab) is Border,"analyzer sidebar uses the simple navigation template: "+tab.Header);}analyzer.AnalyzerPages.SelectedIndex=1;Pump(analyzer);NextStageTests.Draw(analyzer,Path.Combine(root,"analyzer-simple-sidebar.png"));}finally{analyzer.Close();}
   var media=new MediaConverterWindow(owner,new string[0],root,true,delegate{},delegate{});try{Open(media);NavigationTests.Wait(media.AnalysisTask);Click(More(media));Pump(media);double expandedWidth=media.ActualWidth;var nav=(Border)media.SettingsTabs.Template.FindName("Navigation",media.SettingsTabs);
    check(nav.IsVisible&&Math.Abs(nav.ActualHeight-media.SettingsTabs.ActualHeight)<2&&nav.ActualHeight>250,"media sidebar fills the entire workspace instead of the short settings box");
    check(FluentUiTests.Children<DataGrid>(media).Count()==1,"shared media queue remains in the logical control tree");
    foreach(TabItem tab in media.SettingsTabs.Items){tab.ApplyTemplate();check(tab.Template.FindName("NavFrame",tab) is Border,"media sidebar uses the same simple navigation template: "+tab.Header);}
    foreach(int mode in new[]{0,1})foreach(int page in new[]{0,1}){media.Mode.SelectedIndex=mode;media.SettingsTabs.SelectedIndex=page;Pump(media);check(nav.ActualHeight>250&&media.Folder.Text==root,"media mode/page changes preserve full sidebar and destination: "+mode+"/"+page);NextStageTests.Draw(media,Path.Combine(root,"media-sidebar-"+mode+"-"+page+".png"));}
    Click(More(media));Pump(media);check(!nav.IsVisible&&media.ActualWidth<=expandedWidth,"Less hides media navigation while retaining the queue");
    AppearanceTheme.SetMotif("Classic");Pump(media);check(FluentUiTests.Children<DataGrid>(media).Count()==1,"legacy motif requests retain the single media queue");AppearanceTheme.SetMotif("Clean");Pump(media);check(FluentUiTests.Children<DataGrid>(media).Count()==1,"switching back to Clean keeps exactly one media queue");
   }finally{media.Close();AppearanceTheme.SetMotif("Clean");}
