  static void TestPanelDensity(FilePanel[] panels,MainWindow main,string root,Action<bool,string> check){
   panels[0].FocusFiles();Pump(main);check(panels[0].IsActivePanel&&Object.ReferenceEquals(panels[0].BorderBrush,FluentTheme.Accent)&&panels[0].BorderThickness==new Thickness(2),"active panel has a complete two-point blue outline");panels[1].FocusFiles();Pump(main);check(panels[1].IsActivePanel&&Object.ReferenceEquals(panels[1].BorderBrush,FluentTheme.Accent)&&!Object.ReferenceEquals(panels[0].BorderBrush,FluentTheme.Accent),"blue outline moves with keyboard focus to the target panel");panels[0].FocusFiles();Pump(main);
   var rows=Visual<ListViewItem>(panels[0].List).Where(x=>x.IsVisible).ToArray();check(rows.Length>0&&rows.All(x=>x.ActualHeight>=24&&x.ActualHeight<=30),"detail rows use standard compact spacing");
   var saved=ProgramSettings.Load();foreach(double size in new[]{8.0,32.0}){var prefs=new ProgramSettings{DriveIconSize=size,AutoRefresh=false};main.ApplyDisplaySettings(prefs);Pump(main);foreach(var panel in panels){var combo=FluentUiTests.Children<ComboBox>(panel).Single(x=>Convert.ToString(x.Tag)=="drive-selector");var drive=FluentUiTests.Children<Button>(panel).Single(x=>Convert.ToString(x.Tag)=="drive:network");check(Math.Abs(combo.ActualHeight-drive.ActualHeight)<.5,"drive selector matches drive tile height at icon size "+size);check(Convert.ToDouble(combo.Resources["DriveSelectorIconSize"])==size,"drive selector receives configured image size "+size);if(size==8)check(combo.ActualWidth>=80&&combo.ActualWidth<=160&&combo.Items.Cast<DriveChoice>().All(x=>x.IsLocation),"common-folder selector keeps a compact caption-sized frame and omits duplicate drives");else check(combo.ActualWidth>64,"large drive icons also enlarge the selector frame");}}
   NextStageTests.Draw(main,Path.Combine(root,"panel-large-drives.png"));main.ApplyDisplaySettings(saved);Pump(main);NextStageTests.Draw(main,Path.Combine(root,"panel-compact-rows.png"));
   var fixture=new ComboBox{Margin=new Thickness(12),HorizontalAlignment=HorizontalAlignment.Left};DriveSelector.Configure(fixture);var choice=new DriveChoice("C:\\");choice.Update("Fixture","",false,true,DesktopIcons.ToolbarDrawing("folder",ToolbarTheme.Classic));fixture.Items.Add(choice);fixture.SelectedIndex=0;var host=new Window{Content=fixture,Width=420,Height=160};try{Open(host);foreach(double size in new[]{8.0,32.0}){DriveSelector.Resize(fixture,size,size+8,4);fixture.IsDropDownOpen=true;Pump(host);var popup=(System.Windows.Controls.Primitives.Popup)fixture.Template.FindName("PART_Popup",fixture);var icons=Visual<Image>(popup.Child).ToArray();check(icons.Length>0&&icons.All(x=>Math.Abs(x.ActualWidth-size)<.5&&Math.Abs(x.ActualHeight-size)<.5),"expanded drive list scales its actual icons to "+size);fixture.IsDropDownOpen=false;}}finally{host.Close();}
  }
  static void TestPanelCorrections(FilePanel panel,Window main,string root,Action<bool,string> check){
   var columns=((GridView)panel.List.View).Columns;var header=(GridViewColumnHeader)columns[0].Header;
   check(FluentUiTests.Children<DockPanel>(panel).Any(x=>x.Height==38&&x.IsVisible),"single-tab Clean navigation uses one visible tab strip");
   var path=FluentUiTests.Children<Border>(panel).Single(x=>System.Windows.Automation.AutomationProperties.GetAutomationId(x)=="PanelBreadcrumb");
   check(path.IsVisible&&FluentUiTests.Children<Border>(panel).Any(x=>Convert.ToString(x.Tag)=="panel-tab-face"&&x.CornerRadius.BottomLeft==0&&Convert.ToString(x.Background)=="#FFFFFFFF"),"path bar and underline tabs occupy separate rows");
   var menus=FluentUiTests.Children<Menu>(main).ToArray();check(menus.Length>0&&menus.All(x=>Convert.ToString(x.Background)==Convert.ToString(WindowGlass.Layer(main))),"main menu uses the darker reference blue surface");
   header.ContextMenu.IsOpen=true;Pump(main);var choices=header.ContextMenu.Items.OfType<MenuItem>().Where(x=>Convert.ToString(x.Tag)=="Extension"||Convert.ToString(x.Tag)=="Attributes").ToArray();
   check(choices.Length==2&&choices.All(x=>!x.IsChecked),"header menu offers initially hidden extension and attribute columns");
   foreach(var item in choices){item.IsChecked=true;item.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));}header.ContextMenu.IsOpen=false;Pump(main);
   check(columns[1].Width>=25&&columns[4].Width>=25,"header choices reveal extension and attributes");
   check(Visual<TextBlock>(panel.List).Any(x=>x.Text=="Žlutý")&&!Visual<TextBlock>(panel.List).Any(x=>x.Text=="Žlutý.txt"),"separate extension column removes suffix from the name cell");
   var saved=new PanelView();panel.SavePanelView(saved);check(saved.ExtensionColumn==true&&saved.AttributesColumn==true,"base column visibility is captured with panel state");
   var settings=new ProgramSettings{LeftView=saved};settings.Save(Path.Combine(root,"column-options.xml"));var loaded=ProgramSettings.Load(Path.Combine(root,"column-options.xml"));check(loaded.LeftView.ExtensionColumn==true&&loaded.LeftView.AttributesColumn==true,"base column visibility survives XML persistence");
   check(panel.SaveTabs()[panel.CurrentTabIndex].View.ExtensionColumn==true,"saved tabs preserve separate extension column");
   var size=(GridViewColumnHeader)columns[2].Header;size.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Pump(main);
   check(Convert.ToString(size.Content).EndsWith("↑")&&!Convert.ToString(header.Content).Contains("↑"),"ascending sort arrow moves into the selected column");
   size.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));check(Convert.ToString(size.Content).EndsWith("↓"),"clicking sorted column reverses its arrow");
   panel.FocusAddress();Pump(main);check(path.IsVisible&&FluentUiTests.Children<TextBox>(panel).Any(x=>x.IsVisible&&x.IsKeyboardFocusWithin),"address editing uses the path bar while retaining the tabs");panel.FocusFiles();Pump(main);check(path.IsVisible&&FluentUiTests.Children<Border>(panel).Any(x=>Convert.ToString(x.Tag)=="panel-tab-face"&&x.IsVisible),"leaving address editing restores the single tab row");
   panel.NewTab();Pump(main);var tabs=FluentUiTests.Children<Border>(panel).Where(x=>Convert.ToString(x.Tag)=="panel-tab-face").ToArray();check(panel.TabCount==2&&tabs.Length==2&&Math.Abs(tabs[0].TranslatePoint(new Point(),panel).Y-tabs[1].TranslatePoint(new Point(),panel).Y)<1&&path.IsVisible,"multiple tabs share one baseline beneath the path bar");NextStageTests.Draw(main,Path.Combine(root,"real-tabs.png"));
   Click(FluentUiTests.Children<Button>(tabs[0]).Single(x=>x.Content is TextBlock));Pump(main);check(panel.CurrentTabIndex==0,"clicking a tab label changes the active tab");tabs=FluentUiTests.Children<Border>(panel).Where(x=>Convert.ToString(x.Tag)=="panel-tab-face").ToArray();tabs[1].RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,Environment.TickCount,MouseButton.Middle){RoutedEvent=UIElement.PreviewMouseDownEvent});Pump(main);check(panel.TabCount==1&&path.IsVisible&&FluentUiTests.Children<DockPanel>(panel).Any(x=>x.Height==38&&x.IsVisible),"middle-click closes its tab while retaining the path and tab rows");
   NextStageTests.Draw(main,Path.Combine(root,"optional-columns.png"));
   panel.RestorePanelView(new PanelView());Pump(main);NextStageTests.Draw(main,Path.Combine(root,"reference-panels.png"));
   AppearanceTheme.Apply("Dark");Pump(main);check(Convert.ToString(path.Background)=="#FFEDF3F9"&&path.BorderThickness==new Thickness(0)&&menus.All(x=>Convert.ToString(x.Background)==Convert.ToString(WindowGlass.Layer(main))),"legacy dark requests retain the permanent blue-grey palette");AppearanceTheme.Apply("Light");Pump(main);
   check(Convert.ToString(path.Background)=="#FFEDF3F9"&&menus.All(x=>Convert.ToString(x.Background)==Convert.ToString(WindowGlass.Layer(main))),"switching back restores the exact reference blue surfaces");
