  static void TestPause(string root,Action<bool,string> check){
   string heartbeat=Path.Combine(root,"heartbeat.txt");using(var cancel=new CancellationTokenSource())using(var pause=OperationPause.Create(cancel.Token))using(var child=Process.Start(new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"--pause-fixture "+SshTerminal.QuoteWindowsArgument(heartbeat)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){
    try{for(int i=0;i<150&&!File.Exists(heartbeat);i++)Thread.Sleep(20);check(File.Exists(heartbeat),"isolated transaction fixture started");pause.Toggle();var clock=Stopwatch.StartNew();var hold=Task.Run(()=>OperationPause.HoldChild(child,cancel.Token,clock));Thread.Sleep(250);DateTime first=File.GetLastWriteTimeUtc(heartbeat);Thread.Sleep(200);check(!hold.IsCompleted&&first==File.GetLastWriteTimeUtc(heartbeat),"pause actually stops the operation's isolated worker");pause.Toggle();check(hold.Wait(3000),"resume releases the held worker");Thread.Sleep(120);check(File.GetLastWriteTimeUtc(heartbeat)>first,"worker resumes making progress");pause.Toggle();hold=Task.Run(()=>OperationPause.HoldChild(child,cancel.Token,clock));Thread.Sleep(150);cancel.Cancel();try{hold.GetAwaiter().GetResult();}catch(OperationCanceledException){}check(hold.IsCompleted,"cancellation releases a paused worker without stranding suspended threads");}finally{if(!child.HasExited){child.Kill();child.WaitForExit(3000);}}
   }
  }
 }
}
